import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]

@lru_cache(maxsize=None)
def f(mask, last):
    # best maximum reachable when the elements in mask are placed and the last final value is `last`
    best = last
    for j in range(n):
        if mask >> j & 1:
            continue
        for b in range(max(1, last - 1), min(a[j], last + 1) + 1):
            best = max(best, f(mask | (1 << j), b))
    return best

ans = 0
for i in range(n):
    ans = max(ans, f(1 << i, 1))
print(ans)

