    for n in (2, 3, 4, 5, 6, 7):
        for hi in (3, 6, 9):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, N) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt([rng.randint(1, 50) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, N // 2) for _ in range(N)]))
    return tests

